    n = len(grid)
    out = [[0] * (3 * n) for _ in range(3 * n)]
    for r in range(3 * n):
        if r < n:
            rr = n - 1 - r
        elif r < 2 * n:
            rr = r - n
        else:
            rr = 3 * n - 1 - r
        for c in range(3 * n):
            if c < n:
                cc = n - 1 - c
            elif c < 2 * n:
                cc = c - n
            else:
                cc = 3 * n - 1 - c
            out[r][c] = grid[rr][cc]
    return out
